mapper.select:
SELECT SDA.ID, SDA.TYPE, SDA.AREA_TYPE, SDA.AUTHORITY_NAME, SDA.REMARK, SDA.CREATE_TIME, park.park_name FROM SMT_DEVICE_AUTHORITY SDA left join smt_park park on park.id=SDA.park_id
AND SDA.AUTHORITY_NAME LIKE CONCAT(CONCAT('%',#{query.authorityName}),'%')
AND SDA.TYPE = #{query.type}
AND SDA.AREA_TYPE = #{query.areaType}
AND SDA.park_id =#{query.parkId}
AND SDA.device_use_type = #{query.deviceUseType}
and SDA.PARK_ID in
#{item}

SELECT COUNT(SDA.ID)
FROM SMT_DEVICE_AUTHORITY_RELATION SDAR
		 LEFT JOIN SMT_DEVICE_AUTHORITY SDA ON SDAR.AUTHORITY_ID = SDA.ID
WHERE SDAR.DEVICE_ID = #{deviceId}
  AND SDA.AREA_TYPE != #{areaType}
